-- Complete historical disciplines represented in the official 2014 syllabus.
with historical as (
  select id from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Agente de Polícia Federal' and contest_year=2014
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select historical.id,'Histórico',d.discipline,1,d.topic_text,'current'
from historical cross join (values
  ('Atualidades','Temas nacionais e internacionais contemporâneos à aplicação de 2014; material temporal não reutilizável automaticamente.'),
  ('Administração Pública','Teorias administrativas, organização, cultura e gestão pública previstas na edição histórica.'),
  ('Administração Financeira e Orçamentária','Orçamento público e princípios orçamentários previstos na edição histórica.'),
  ('Ética no Serviço Público','Ética, deveres e conduta do servidor previstos na edição histórica.'),
  ('Economia','Microeconomia e estruturas de mercado previstas na edição histórica.')
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

create table if not exists public.official_exam_questions (
  id uuid primary key default gen_random_uuid(),
  question_source_id uuid not null references public.content_sources(id),
  answer_key_source_id uuid not null references public.content_sources(id),
  syllabus_topic_id uuid not null references public.syllabus_topics(id),
  contest_name text not null default 'Polícia Federal',
  exam_year integer not null,
  career_name text not null default 'Agente de Polícia Federal',
  exam_board text not null default 'CEBRASPE',
  item_number integer not null check (item_number between 1 and 120),
  subject text not null,
  question_text text not null,
  raw_extraction text not null,
  official_answer text not null check (official_answer in ('C','E','X')),
  source_page integer not null,
  content_status text not null check (content_status in ('active','under_review','annulled','obsolete','revoked','archived')),
  legal_review_required boolean not null default false,
  context_review_required boolean not null default false,
  legal_basis jsonb not null default '[]'::jsonb,
  law_version_checked_at timestamptz,
  review_note text not null,
  verified_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  unique (exam_year,item_number)
);

alter table public.official_exam_questions enable row level security;
drop policy if exists "Students read active official exam questions" on public.official_exam_questions;
create policy "Students read active official exam questions" on public.official_exam_questions
  for select to authenticated using (content_status='active');
drop policy if exists "Admins manage all official exam questions" on public.official_exam_questions;
create policy "Admins manage all official exam questions" on public.official_exam_questions
  for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));

create index if not exists idx_official_exam_questions_filters
  on public.official_exam_questions(content_status,exam_year,subject,item_number);

-- Correct a typographical reference in the active syllabus without changing scope.
update public.syllabus_topics
set topic_text=replace(topic_text,'Lei nº 9.545/1997','Lei nº 9.455/1997')
where discipline='Legislação Especial' and topic_text like '%Lei nº 9.545/1997%';

with imported(exam_year,item_number,subject,question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,context_review_required,review_note) as (values
(2014,1,'Língua Portuguesa','No texto, os termos “matéria-prima” ( R.8), “instalações fixas (edifícios)” ( R.8) e “instrumentos de produção (máquinas)” (R.9) são exemplos de “meios de produção” (R.4).','No texto, os termos “matéria-prima” ( R.8), “instalações fixas (edifícios)” ( R.8) e “instrumentos de produção (máquinas)” (R.9) são exemplos de “meios de produção” (R.4).','C',2,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,2,'Língua Portuguesa','Infere-se do texto que todo economista é capitalista, mas o inverso não é verdadeiro, pois nem todo capitalista é proprietário de empresa.','Infere-se do texto que todo economista é capitalista, mas o inverso não é verdadeiro, pois nem todo capitalista é proprietário de empresa.','E',2,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,3,'Língua Portuguesa','Não haveria alteração de sentido do texto, caso o trecho “todos reconhecem, porque (...) d’ O Capital , que não há produção” ( R. 1 e 2) fosse reescrito da seguinte forma: todos reconhecem a razão pela qual Marx impôs esta demonstração no Livro II d’ O Capital — que não há produção.','Não haveria alteração de sentido do texto, caso o trecho “todos reconhecem, porque (...) d’ O Capital , que não há produção” ( R. 1 e 2) fosse reescrito da seguinte forma: todos reconhecem a razão pela qual Marx impôs esta demonstração no Livro II d’ O Capital — que não há produção.','E',2,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,4,'Língua Portuguesa','O trecho “que não há produção possível (...) dos meios de produção” ( R. 2 a 4) é a demonstração a que se refere a expressão “esta demonstração” (R. 1 e 2).','O trecho “que não há produção possível (...) dos meios de produção” ( R. 2 a 4) é a demonstração a que se refere a expressão “esta demonstração” (R. 1 e 2). Imigrantes ilegais, os homens e as mulheres vieram1 para Prato, na Itália, como parte de snakebodies liderados por snakeheads na Europa. Em outras palavras, fizeram a perigosa viagem da China por trem, caminhão, a pé e por mar como4 parte de um grupo pequeno, aterrorizado, que confiou seu destino a gangues chinesas que administram as maiores redes de contrabando de gente no mundo. Nos locais em que suas 7 viagens começaram, havia filhos, pais, esposas e outros que dependiam deles para que enviassem dinheiro. No destino, havia paredes cobertas com anúncios de mau gosto de10 empregos que representavam a esperança de uma vida melhor. Pedi a um dos homens ao lado da parede que me contasse como tinha sido sua viagem. Ele objetou. Membros do13 snakebody têm de jurar segredo aos snakeheads que organizam sua viagem. Tive de convencê-lo, concordando em usar um nome falso e camuflar outros aspectos de sua jornada. Depois16 de uma série de encontros e entrevistas, pelos quais paguei alguma coisa, a história de como Huang chegou a Prato emergiu lentamente. 19 James Kynge. A China sacode o mundo . São Paulo: Globo, 2007 (com adaptações). Julgue os seguintes itens, relativos às ideias e às estruturas linguísticas do texto acima.','C',2,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,5,'Língua Portuguesa','Depreende-se do texto que chineses emigram para a Europa em busca da possibilidade de melhor sustento financeiro de suas famílias.','Depreende-se do texto que chineses emigram para a Europa em busca da possibilidade de melhor sustento financeiro de suas famílias.','C',2,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,6,'Língua Portuguesa','A correção gramatical do texto seria preservada caso se substituísse a locução “tinha sido” ( R.13) pela forma verbal fora.','A correção gramatical do texto seria preservada caso se substituísse a locução “tinha sido” ( R.13) pela forma verbal fora.','C',2,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,7,'Língua Portuguesa','Os termos “série” e “história” acentuam-se em conformidade com a mesma regra ortográfica.','Os termos “série” e “história” acentuam-se em conformidade com a mesma regra ortográfica.','C',2,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,8,'Língua Portuguesa','O texto é narrativo e autobiográfico, o que se evidencia pelo uso da primeira pessoa do singular no segundo parágrafo, quando é contado um fato acontecido ao narrador.','O texto é narrativo e autobiográfico, o que se evidencia pelo uso da primeira pessoa do singular no segundo parágrafo, quando é contado um fato acontecido ao narrador.','E',2,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,9,'Língua Portuguesa','Os termos “febre” ( R.24), “antitérmico” ( R.27) e “paliativo” (R.27) expressam a analogia do tráfico de pessoas e do trabalho escravo na atualidade com um padrão doentio cuja erradicação passa pela libertação dos trabalhadores, embora não se limite a ela.','Os termos “febre” ( R.24), “antitérmico” ( R.27) e “paliativo” (R.27) expressam a analogia do tráfico de pessoas e do trabalho escravo na atualidade com um padrão doentio cuja erradicação passa pela libertação dos trabalhadores, embora não se limite a ela.','C',3,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,10,'Língua Portuguesa','Segundo o texto, a devastação do meio ambiente e a exploração de mão de obra escrava caracterizam o modelo de desenvolvimento atual.','Segundo o texto, a devastação do meio ambiente e a exploração de mão de obra escrava caracterizam o modelo de desenvolvimento atual.','C',3,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,11,'Língua Portuguesa','Infere-se do texto a existência de dois segmentos que lucram com o tráfico de pessoas: as empresas, que reduzem os custos com mão de obra, e os intermediários, que se beneficiam da exploração de pessoas que desejam migrar.','Infere-se do texto a existência de dois segmentos que lucram com o tráfico de pessoas: as empresas, que reduzem os custos com mão de obra, e os intermediários, que se beneficiam da exploração de pessoas que desejam migrar.','C',3,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,12,'Língua Portuguesa','O sentido original do texto seria preservado caso a forma verbal “eram capturados” ( R.8) fosse substituída por foram capturados.','O sentido original do texto seria preservado caso a forma verbal “eram capturados” ( R.8) fosse substituída por foram capturados.','E',3,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,13,'Língua Portuguesa','No texto, as expressões “esses verbos” ( R.1) e “Esse ciclo” (R.12) têm a mesma finalidade: retomar termos ou ideias expressos anteriormente.','No texto, as expressões “esses verbos” ( R.1) e “Esse ciclo” (R.12) têm a mesma finalidade: retomar termos ou ideias expressos anteriormente. O tráfico internacional de drogas começou a desenvolver-se em meados da década de 70, tendo tido o seu boom na década de 80. Esse desenvolvimento está estreitamente ligado à crise econômica mundial. O narcotráfico determina as economias dos países produtores de coca e, ao mesmo tempo, favorece principalmente o sistema financeiro mundial. O dinheiro oriundo da droga corresponde à lógica do sistema financeiro, que é eminentemente especulativo. Este necessita, cada vez mais, de capital “livre” para girar, e o tráfico de drogas promove o “aparecimento mági co” desse capital que se acumula de modo rápido e se move velozmente. A América Latina participa do narcotráfico na qualidade de maior produtora mundial de cocaína, e um de seus países, a Colômbia, detém o controle da maior parte do tráfico internacional. A cocaína gera “dependência” em grupos econômicos e até mesmo nas economias de alguns países, como nos bancos da Flórida, em algumas ilhas do Caribe ou nos principais países produtores — Peru, Bolívia e Colômbia, para citar apenas os casos de maior destaque. Na Bolívia, os lucros com o narcotráfico chegam a US$ 1,5 bilhão contra US$ 2,5 bilhões das exportações legais. Na Colômbia, o narcotráfico gera de US$ 2 a 4 bilhões, enquanto as exportações oficiais geram US$ 5,25 bilhões. Nesses países, a corrupção é generalizada. Os narcotraficantes controlam o governo, as forças armadas, o corpo diplomático e até as unidades encarregadas do combate ao tráfico. Não há setor da sociedade que não tenha ligação com os traficantes e até mesmo a Igreja recebe contribuições destes. Osvaldo Coggiola. O comércio de drogas hoje . In: Olho da História, n.o 4. Internet: <www.oolhodahistoria.ufba.br> (com adaptações). Julgue os próximos itens, referentes aos sentidos do texto acima.','C',3,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,14,'Língua Portuguesa','Verifica-se no texto uma ampliação de sentido do termo “dependência”: da dependência química causada em usuários de drogas à dependência de grupos e países cuja economia lucra com o narcotráfico.','Verifica-se no texto uma ampliação de sentido do termo “dependência”: da dependência química causada em usuários de drogas à dependência de grupos e países cuja economia lucra com o narcotráfico.','C',3,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,15,'Língua Portuguesa','Depreende-se do texto uma discrepância na ligação do narcotráfico com a Igreja e com unidades de combate ao tráfico.','Depreende-se do texto uma discrepância na ligação do narcotráfico com a Igreja e com unidades de combate ao tráfico.','E',3,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,16,'Língua Portuguesa','Infere-se do texto que o lucro com o narcotráfico equivale a duas vezes o lucro com as exportações legais tanto na Bolívia quanto na Colômbia.','Infere-se do texto que o lucro com o narcotráfico equivale a duas vezes o lucro com as exportações legais tanto na Bolívia quanto na Colômbia.','E',3,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,17,'Língua Portuguesa','O texto, que se classifica como dissertativo, expõe a articulação entre o tráfico internacional de drogas e o sistema financeiro mundial.','O texto, que se classifica como dissertativo, expõe a articulação entre o tráfico internacional de drogas e o sistema financeiro mundial.','C',3,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,18,'Língua Portuguesa','A forma verbal “infligem” (R.4) está empregada no texto com o mesmo sentido que está empregada na seguinte frase: Os agentes de trânsito infligem multas aos infratores.','A forma verbal “infligem” (R.4) está empregada no texto com o mesmo sentido que está empregada na seguinte frase: Os agentes de trânsito infligem multas aos infratores.','E',4,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,19,'Língua Portuguesa','Nas linhas 12 e 13, o emprego da preposição “com”, em “com a criminalidade e a violência”, deve-se à regência do vocábulo “conexos”.','Nas linhas 12 e 13, o emprego da preposição “com”, em “com a criminalidade e a violência”, deve-se à regência do vocábulo “conexos”.','E',4,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,20,'Língua Portuguesa','O referente do sujeito da oração “articulando-se internamente e com a sociedade” (R. 16 e 17), que está elíptico no texto, é “o governo” (R.15).','O referente do sujeito da oração “articulando-se internamente e com a sociedade” (R. 16 e 17), que está elíptico no texto, é “o governo” (R.15).','C',4,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,21,'Língua Portuguesa','Caso o termo “na atualidade” ( R.1) fosse deslocado para imediatamente após “drogas” (R.1), e fossem feitos os devidos ajustes na pontuação do texto, a correção gramatical do texto seria mantida, mas haveria prejuízo para seu sentido original.','Caso o termo “na atualidade” ( R.1) fosse deslocado para imediatamente após “drogas” (R.1), e fossem feitos os devidos ajustes na pontuação do texto, a correção gramatical do texto seria mantida, mas haveria prejuízo para seu sentido original.','X',4,'annulled',false,true,'Item anulado no gabarito oficial definitivo; não é exibido aos estudantes.'),
(2014,22,'Língua Portuguesa','Na linha 6, dados os sentidos do trecho introduzido por dois-pontos, o vocábulo “fronteiras” deve ser interpretado em sentido amplo, não estando restrito ao seu sentido denotativo.','Na linha 6, dados os sentidos do trecho introduzido por dois-pontos, o vocábulo “fronteiras” deve ser interpretado em sentido amplo, não estando restrito ao seu sentido denotativo.','C',4,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,23,'Língua Portuguesa','O acento indicativo de crase em “à humanidade e à estabilidade” ( R.2) é de uso facultativo, razão por que sua supressão não prejudicaria a correção gramatical do texto.','O acento indicativo de crase em “à humanidade e à estabilidade” ( R.2) é de uso facultativo, razão por que sua supressão não prejudicaria a correção gramatical do texto.','E',4,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,24,'Língua Portuguesa','O pronome possessivo “Suas” ( R.4) refere-se a “de todos os Estados e sociedades” (R. 3 e 4).','O pronome possessivo “Suas” ( R.4) refere-se a “de todos os Estados e sociedades” (R. 3 e 4). Julgue os itens que se seguem, relativos a aspectos gerais da redação oficial.','E',4,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,25,'Língua Portuguesa','Quando se utiliza o memorando, os despachos devem ser dados no próprio documento. Nesse caso, se o espaço disponível for insuficiente para todos os despachos, devem-se usar folhas de continuação.','Quando se utiliza o memorando, os despachos devem ser dados no próprio documento. Nesse caso, se o espaço disponível for insuficiente para todos os despachos, devem-se usar folhas de continuação.','C',4,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,26,'Língua Portuguesa','As comunicações oficiais podem ser remetidas em nome do serviço público ou da pessoa que ocupa determinado cargo dentro do serviço público.','As comunicações oficiais podem ser remetidas em nome do serviço público ou da pessoa que ocupa determinado cargo dentro do serviço público. Com referência à adequação da linguagem ao tipo de documento e à adequação do formato do texto ao gênero, julgue os seguintes itens.','E',4,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,27,'Língua Portuguesa','Os expedientes que seguem o padrão ofício são documentos que compartilham as mesmas partes e a mesma diagramação, como, por exemplo, o aviso, o memorando e a mensagem.','Os expedientes que seguem o padrão ofício são documentos que compartilham as mesmas partes e a mesma diagramação, como, por exemplo, o aviso, o memorando e a mensagem.','E',4,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,28,'Língua Portuguesa','A identificação do signatário em expediente não remetido pelo presidente da República deve ser feita pelo nome e pelo cargo da autoridade expedidora do documento.','A identificação do signatário em expediente não remetido pelo presidente da República deve ser feita pelo nome e pelo cargo da autoridade expedidora do documento.','C',4,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,29,'Língua Portuguesa','A forma de tratamento “Vossa Excelência” é adequada para se dirigir a um secretário de segurança pública estadual.','A forma de tratamento “Vossa Excelência” é adequada para se dirigir a um secretário de segurança pública estadual.','C',4,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2014,30,'Língua Portuguesa','O fecho “Respeitosamente”, por sua formalidade e impessoalidade, pode ser empregado em qualquer tipo de expediente, independentemente do seu subscritor e do seu destinatário.','O fecho “Respeitosamente”, por sua formalidade e impessoalidade, pode ser empregado em qualquer tipo de expediente, independentemente do seu subscritor e do seu destinatário. Julgue os itens a seguir, relativos aos sistemas operacionais Linux e Microsoft Word 2013.','E',4,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
