(2018,97,'Contabilidade Geral','Sob a ótica citada, o objeto da contabilidade é o patrimônio do ente contábil específico.','Sob a ótica citada, o objeto da contabilidade é o patrimônio do ente contábil específico.','C',8,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
