(2021,12,'Língua Portuguesa','Conclui-se do trecho ‘há uma crescente necessidade de disciplinar importantes grupo s e segmentos populacionais’ que os grupos populacionais a serem disciplinados são compostos por pessoas que têm autoridade e gozam de prestígio na sociedade, do que s e infere que tais grupos têm adotado comportamentos indesejáveis.','Conclui-se do trecho ‘há uma crescente necessidade de disciplinar importantes grupo s e segmentos populacionais’ que os grupos populacionais a serem disciplinados são compostos por pessoas que têm autoridade e gozam de prestígio na sociedade, do que s e infere que tais grupos têm adotado comportamentos indesejáveis.','E',3,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2021,13,'Língua Portuguesa','A forma verbal “crescem” (ter ceiro período do primeiro parágrafo) está flexionada no plural para concordar com o sujeito composto cujos núcleos são “gastos”, “efetivos” e “serviços”.','A forma verbal “crescem” (ter ceiro período do primeiro parágrafo) está flexionada no plural para concordar com o sujeito composto cujos núcleos são “gastos”, “efetivos” e “serviços”.','E',3,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2021,14,'Língua Portuguesa','O travessão empregado no último período do primeiro parágrafo confere ao trecho final do período, por ele isolado, um destaque, mas sua supressão manteria a correção gramatical do texto.','O travessão empregado no último período do primeiro parágrafo confere ao trecho final do período, por ele isolado, um destaque, mas sua supressão manteria a correção gramatical do texto. Ainda com relação ao texto 2A1-II, julgue os itens subsecutivos.','C',3,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
