(2021,57,'Raciocínio Lógico','O argumento apresentado não é válido.','O argumento apresentado não é válido. Considere os seguintes conjuntos: P = {todos os policiais federais em efetivo exercício no país} P1 = {policiais federais em efetivo exercício no país e que têm até 1 ano de experiência no exercício do cargo} P2 = {policiais federais em efetivo exercício no país e que têm até 2 anos de experiência no exercício do cargo} P3 = {policiais federais em efetivo exercício no país e que têm até 3 anos de experiência no exercício do cargo} e, assim, sucessivamente. Com base nessas informações, julgue os itens que se seguem.','C',6,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2021,58,'Raciocínio Lógico','O c o n j u n t o P é i g u a l à u n i ã o i n f i n i t a d o s c o n j u n t o s P1, P 2, P3, ...','O c o n j u n t o P é i g u a l à u n i ã o i n f i n i t a d o s c o n j u n t o s P1, P 2, P3, ...','C',6,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2021,59,'Raciocínio Lógico','P2 é subconjunto de P1.','P2 é subconjunto de P1.','E',6,'under_review',false,true,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
(2021,60,'Raciocínio Lógico','Escolhendo-se aleatoriamente um integrante do conjunto P, a probabilidade de ele ter entre doi s e três anos de experiência no exercício do cargo é dada por n(P 2 – P3)/n(P3), em que n(X) indica o número de elementos do conjunto X e P2 – P3 é o conjunto formado pelos indivíduos que estão em P 2, mas não estão em P3.','Escolhendo-se aleatoriamente um integrante do conjunto P, a probabilidade de ele ter entre doi s e três anos de experiência no exercício do cargo é dada por n(P 2 – P3)/n(P3), em que n(X) indica o número de elementos do conjunto X e P2 – P3 é o conjunto formado pelos indivíduos que estão em P 2, mas não estão em P3. Espaço livre','E',6,'under_review',false,false,'Item histórico aguardando confronto individual com o edital PF 2025 e fontes vigentes.'),
